package com.fantasymap.creator.model

/**
 * Собственные значки объектов, у которых раньше был общий знак с другими.
 *
 * Значок описан строкой фигур в квадрате [-1, 1] (y вниз), фигуры через «;»:
 *  P x y x y … — многоугольник с заливкой и контуром;
 *  S x y …     — многоугольник, залитый цветом контура (тёмные проёмы, окна);
 *  B x y …     — сглаженный замкнутый контур с заливкой;
 *  L x y …     — ломаная; Z x y … — сглаженная линия;
 *  E cx cy rx ry — эллипс с заливкой; O … — только контур; K … — тёмный эллипс;
 *  A cx cy rx ry start sweep — дуга в градусах.
 * Проверяется тестом MarkerIconsTest: у каждого объекта значок, которого нет ни у кого больше.
 */
object MarkerIcons {

    class Op(val kind: Char, val v: FloatArray)

    /** Описание значка или null, если объект рисуется своим знаком [MarkerType.glyph]. */
    fun source(type: MarkerType): String? = sources[type.name]

    fun parse(src: String): List<Op> = src.split(';').map { part ->
        val t = part.trim()
        val kind = t[0]
        val v = t.substring(1).trim().split(' ').filter { it.isNotEmpty() }.map { it.toFloat() }.toFloatArray()
        val ok = when (kind) {
            'P', 'S', 'B' -> v.size >= 6 && v.size % 2 == 0
            'L', 'Z' -> v.size >= 4 && v.size % 2 == 0
            'E', 'O', 'K' -> v.size == 4
            'A' -> v.size == 6
            else -> false
        }
        require(ok) { "Неверная фигура значка: $t" }
        Op(kind, v)
    }

